# clamp :: (5, 0, 10)
def clamp(x, lo, hi):
    return max(lo, min(hi, x))

if __name__ == '__main__':
    print(clamp((5, 0, 10)))

# clamp :: (-1, 0, 10)
def clamp(x, lo, hi):
    return max(lo, min(hi, x))

if __name__ == '__main__':
    print(clamp((-1, 0, 10)))

